package dev.mesbase.server;
@org.springframework.context.annotation.Configuration @org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name="mes.system.enabled",havingValue="true")
public class SystemRedisConfiguration {
 @org.springframework.context.annotation.Bean("redisTemplate") public org.springframework.data.redis.core.RedisTemplate<String,Object> redisTemplate(org.springframework.data.redis.connection.RedisConnectionFactory factory){var template=new org.springframework.data.redis.core.RedisTemplate<String,Object>();template.setConnectionFactory(factory);var keys=new org.springframework.data.redis.serializer.StringRedisSerializer();template.setKeySerializer(keys);template.setHashKeySerializer(keys);template.setValueSerializer(new org.springframework.data.redis.serializer.JdkSerializationRedisSerializer());template.setHashValueSerializer(new org.springframework.data.redis.serializer.JdkSerializationRedisSerializer());template.afterPropertiesSet();return template;}
 @org.springframework.context.annotation.Bean org.springframework.boot.web.servlet.FilterRegistrationBean<dev.mesbase.common.filter.XssFilter> xss(org.springframework.core.env.Environment env){var r=new org.springframework.boot.web.servlet.FilterRegistrationBean<>(new dev.mesbase.common.filter.XssFilter());r.setEnabled(env.getProperty("xss.enabled",Boolean.class,true));r.setOrder(org.springframework.core.Ordered.HIGHEST_PRECEDENCE+30);r.addUrlPatterns(env.getProperty("xss.url-patterns","/api/system/*,/api/monitor/*").split(","));r.addInitParameter("excludes",env.getProperty("xss.excludes","/api/system/user/profile/updatePwd"));return r;}
}
